-- Classic 1.60: vanilla pet base stats (VMaNGOS pet_levelstats): hunter pets (1), Imp 416, Voidwalker 1860, Succubus 1863,
-- Felhunter 417 and the summoned pets 329, 510, 15214. Ours were later expansion values (Imp level 10 223 health instead
-- of 64, Voidwalker level 60 4745 armor instead of 4660). Levels above 60 of these pets are left as they were.
DELETE FROM `pet_levelstats` WHERE `creature_entry` IN (1,15214,1860,1863,329,416,417,510) AND `level` <= 63;
